-- Generated by Ingestron from flows/shop.yaml (table orders). Do not edit: change the definitions and generate again.
-- Changes as received, each read once.
CREATE OR REFRESH STREAMING TABLE `bronze`.`orders_changes`
AS SELECT * FROM STREAM read_files(
  '${ingestron.shop_path}/orders',
  format => 'parquet',
  schemaHints => '`id` BIGINT, `customer_id` BIGINT, `ordered_at` TIMESTAMP, `total` DECIMAL(18,2), `updated_at` TIMESTAMP, `op` STRING, `card_last4` STRING',
  schemaEvolutionMode => 'addNewColumns'
);

-- The current rows, kept by key.
CREATE OR REFRESH STREAMING TABLE `bronze`.`orders` (
  CONSTRAINT `id_not_null` EXPECT (`id` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `customer_id_not_null` EXPECT (`customer_id` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `ordered_at_not_null` EXPECT (`ordered_at` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `updated_at_not_null` EXPECT (`updated_at` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `positive_total` EXPECT (total >= 0)
)
COMMENT 'One row per order, kept current.'
CLUSTER BY AUTO
TBLPROPERTIES ('delta.enableChangeDataFeed' = 'true');

CREATE FLOW `orders_cdc`
AS AUTO CDC INTO `bronze`.`orders`
FROM STREAM(`bronze`.`orders_changes`)
KEYS (`id`)
APPLY AS DELETE WHEN op = 'D'
SEQUENCE BY `updated_at`
COLUMNS * EXCEPT (`op`)
STORED AS SCD TYPE 1;
